"""Path33 — pure own-stack submission: every model is ours.

Arms (equal rank-mean of four family outputs):
  A. dino2b_fx1  — DINOv2-base member, 5 folds  (OOF 0.7953)  @336/130mm
  B. dino2s_fx1  — DINOv2-small member, 5 folds (OOF 0.7915)  @336/130mm
  C. dino2b_v3f0 — bag-sampled member, fold 0   (OOF 0.8005)  @224/150mm
  D. raptorx1    — whole-volume CoAtNet, SWA    (holdout 0.786) @224/140mm

Purpose: the first honest LB read of the own line since the recipe fixes —
calibrates the scanner-OOF -> LB mapping for the 5-fold program. No public
weights anywhere. Every stage asserts; no silent fallbacks.
"""

import base64
import importlib.util
import json
import os
import time
from pathlib import Path

import numpy as np
import pandas as pd

WORK = Path("/kaggle/working")
T0 = time.time()

P27_B64 = ""   # fx members' module (336/130, 9 slices)
P32_B64 = ""   # v3 member's module (224/150, 12 slices, eval starts)
P31_B64 = ""   # raptorx module (volume cache + window_stack)

TARGETS = ["ACL", "MCL", "Medial Meniscus", "Lateral Meniscus", "Medial OA",
           "Lateral OA", "PF OA", "Effusion", "Synovitis", "Baker's",
           "Contusion", "Fracture"]


def log(msg):
    print(f"[p33 {time.time() - T0:7.1f}s] {msg}", flush=True)


def load_module(b64, name):
    path = WORK / f"p33_{name}.py"
    path.write_bytes(base64.b64decode(b64))
    spec = importlib.util.spec_from_file_location(name, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def find_files(pattern_prefix, suffix=".pt", expect=None):
    hits = []
    for root, dirs, files in os.walk("/kaggle/input"):
        dirs[:] = [d for d in dirs if d not in ("train_series", "test_series")]
        for f in files:
            if f.startswith(pattern_prefix) and f.endswith(suffix):
                hits.append(Path(root) / f)
    hits = sorted(hits)
    if expect is not None and len(hits) != expect:
        raise FileNotFoundError(f"{pattern_prefix}*: expected {expect}, found {len(hits)}: {hits}")
    return hits


def slot_member_predictions(mod, tags_models, test_df, root):
    """Build one slot cache with `mod`'s geometry; run each (tag, model_key)'s
    fold checkpoints; return dict tag -> fold-rank-mean matrix."""
    import torch

    series = mod.list_series(root / "test_series", pd.read_csv(root / "test_series.csv"),
                             set(test_df["StudyInstanceUID"]))
    slots = mod.choose_slots(series)
    headers, probes = mod.study_headers(slots)
    sides = mod.laterality_map(probes)
    studies, cache, mask = mod.build_cache(slots, sides, f"p33-{mod.MEMBER_TAG}")
    if len(studies) != len(test_df):
        raise RuntimeError(f"cache covers {len(studies)}/{len(test_df)} studies")
    device = torch.device("cuda")
    out = {}
    for tag, model_key, n_folds in tags_models:
        ckpts = find_files(f"{tag}_fold", expect=n_folds)
        mod.MODEL_KEY = model_key
        backbone_path = mod.find_backbone()
        ranked = []
        for ck_path in ckpts:
            ck = torch.load(ck_path, map_location="cpu", weights_only=False)
            if ck.get("img_size") != mod.IMG_SIZE or ck.get("cache_slices") != mod.CACHE_SLICES:
                raise ValueError(f"{ck_path.name}: geometry mismatch with module")
            model = mod.build_model(backbone_path)
            model.load_state_dict(ck["state_dict"], strict=True)
            model = model.to(device)
            preds = mod.predict(model, cache, mask, np.arange(len(studies)), device)
            if not np.isfinite(preds).all():
                raise RuntimeError(f"{ck_path.name}: non-finite predictions")
            ranked.append(mod.rank_predictions(preds))
            del model
            torch.cuda.empty_cache()
            log(f"{tag}: {ck_path.name} done")
        out[tag] = (studies, np.mean(ranked, axis=0))
    del cache
    return out


def raptorx_predictions(mod31, test_df, root):
    import timm
    import torch
    import torch.nn as nn

    p27 = mod31.load_p27()
    series = p27.list_series(root / "test_series", pd.read_csv(root / "test_series.csv"),
                             set(test_df["StudyInstanceUID"]))
    slots = p27.choose_slots(series)
    headers, probes = p27.study_headers(slots)
    sides = p27.laterality_map(probes)
    studies, cache = mod31.build_volume_cache(p27, slots, sides, "p33-raptorx")

    ck = torch.load(find_files("raptorx1_swa", expect=1)[0], map_location="cpu", weights_only=False)
    device = torch.device("cuda")
    backbone = timm.create_model(ck["backbone"], pretrained=False, num_classes=0)
    dim = backbone.num_features
    modules = nn.ModuleDict({
        "backbone": backbone, "norm": nn.LayerNorm(dim),
        "att": nn.Linear(dim, 12), "cls": nn.Linear(dim, 12),
    })
    modules.load_state_dict(ck["state_dict"], strict=True)
    modules = modules.to(device).eval()
    mean = torch.tensor([0.485, 0.456, 0.406]).view(1, 3, 1, 1).to(device)
    std = torch.tensor([0.229, 0.224, 0.225]).view(1, 3, 1, 1).to(device)

    outs = []
    with torch.no_grad():
        for s in range(0, len(studies), 2):
            wins, _ = mod31.window_stack(cache[s:s + 2], device)
            B, K = wins.shape[:2]
            flat = (wins.reshape(B * K, *wins.shape[2:]) - mean) / std
            with torch.autocast("cuda"):
                feats = modules["backbone"](flat).reshape(B, K, -1)
                h = modules["norm"](feats)
                att = torch.softmax(modules["att"](h), dim=1)
                logits = (att * modules["cls"](h)).sum(dim=1)
            outs.append(torch.sigmoid(logits).float().cpu().numpy())
    preds = np.concatenate(outs)
    if not np.isfinite(preds).all():
        raise RuntimeError("raptorx: non-finite predictions")
    frame = pd.DataFrame(preds, columns=TARGETS)
    return studies, frame.rank(method="average", pct=True).values.astype(np.float32)


def main():
    mod27 = load_module(P27_B64, "p27mod")
    mod32 = load_module(P32_B64, "p32mod")
    mod31 = load_module(P31_B64, "p31mod")
    root = mod27.find_competition_root()
    test_df = pd.read_csv(root / "test.csv")

    fx = slot_member_predictions(mod27, [("dino2b_fx1", "base", 5), ("dino2s_fx1", "small", 5)],
                                 test_df, root)
    v3 = slot_member_predictions(mod32, [("dino2b_v3f0", "base", 1)], test_df, root)
    rx_studies, rx = raptorx_predictions(mod31, test_df, root)

    ref_studies = fx["dino2b_fx1"][0]
    arms = {"fx_base": fx["dino2b_fx1"][1], "fx_small": fx["dino2s_fx1"][1]}
    for name, (studies, mat) in (("v3f0", v3["dino2b_v3f0"]), ("raptorx", (rx_studies, rx))):
        if studies != ref_studies:
            order = {s: i for i, s in enumerate(studies)}
            mat = mat[[order[s] for s in ref_studies]]
        arms[name] = mat

    blend = np.mean(list(arms.values()), axis=0)
    out = pd.DataFrame(pd.DataFrame(blend).rank(method="average", pct=True).values, columns=TARGETS)
    out.insert(0, "StudyInstanceUID", ref_studies)
    final = test_df[["StudyInstanceUID"]].merge(out, on="StudyInstanceUID", validate="one_to_one")
    if final[TARGETS].isna().any().any():
        raise RuntimeError("missing predictions after merge")
    final.to_csv(WORK / "submission.csv", index=False)
    audit = {
        "mode": "path33-own-stack",
        "arms": {"fx_base": "5-fold OOF 0.7953", "fx_small": "5-fold OOF 0.7915",
                 "v3f0": "fold-0 OOF 0.8005", "raptorx": "SWA holdout 0.7859"},
        "fusion": "equal rank-mean of 4 own arms",
        "n_studies": int(len(final)),
        "public_weights_used": False,
        "elapsed_seconds": round(time.time() - T0, 1),
        "status": "PATH33_SUBMISSION_WRITTEN",
    }
    (WORK / "p33_audit.json").write_text(json.dumps(audit, indent=2))
    log(json.dumps(audit, indent=2))


if __name__ == "__main__":
    main()
